-- Original CrossSmudge suit art, packed into immutable byte strings.
local S14="\192\000\224\001\240\003\248\007\252\015\254\031\255\063\255\063\254\031\231\057\193\032\192\000\240\003\248\007\030\030\063\063\051\051\003\048\003\048\006\024\012\012\024\006\048\003\224\001\192\000\192\000\000\000\000\000\224\001\240\003\240\003\224\001\207\060\255\063\255\063\255\063\254\031\240\003\192\000\224\001\240\003\248\007\192\000\224\001\048\003\024\006\012\012\006\024\003\048\003\048\006\024\012\012\024\006\048\003\224\001\192\000"
local S22="\000\012\000\000\030\000\000\063\000\128\127\000\192\255\000\224\255\001\240\255\003\248\255\007\252\255\015\254\255\031\255\255\063\255\255\063\255\255\063\254\255\031\031\063\062\007\030\056\001\012\032\000\012\000\000\030\000\128\127\000\224\255\001\248\255\007\248\192\007\252\225\015\254\243\031\007\063\056\003\030\048\003\012\048\003\000\048\003\000\048\006\000\024\006\000\024\012\000\012\024\000\006\048\000\003\096\128\001\192\192\000\128\097\000\000\051\000\000\030\000\000\012\000\000\012\000\000\000\000\000\000\000\000\063\000\128\127\000\192\255\000\192\255\000\128\127\000\000\063\000\063\030\063\255\222\063\255\255\063\255\255\063\255\255\063\255\255\063\254\255\031\252\255\015\240\255\003\128\127\000\000\012\000\000\030\000\000\063\000\128\127\000\224\255\001\248\255\007\000\012\000\000\030\000\000\063\000\128\097\000\192\192\000\096\128\001\048\000\003\024\000\006\012\000\012\006\000\024\003\000\048\003\000\048\006\000\024\012\000\012\024\000\006\048\000\003\096\128\001\192\192\000\128\097\000\000\063\000\000\030\000\000\012\000"
local function draw(data,size,bytes,x,y,suit,color)
 local base=(suit-1)*size*bytes
 for row=0,size-1 do local bits=0
  for b=0,bytes-1 do bits=bits|(data:byte(base+row*bytes+b+1)<<(b*8)) end
  local col=0
  while col<size do if bits&(1<<(size-col-1))~=0 then local first=col;repeat col=col+1 until col==size or bits&(1<<(size-col-1))==0;smudge.rect(x+first,y+row,col-first,1,true,color) else col=col+1 end end
 end
end
function draw_suit_14(x,y,suit,color) draw(S14,14,2,x,y,suit,color) end
function draw_suit_22(x,y,suit,color) draw(S22,22,3,x,y,suit,color) end
